          ..write('mode: $mode, ')
          ..write('wpm: $wpm, ')
          ..write('words: $words, ')
          ..write('activeMs: $activeMs, ')
          ..write('backs: $backs, ')
          ..write('pauses: $pauses, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

